BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'What is a ''tappet'' (cam) shedding mechanism, and for what type of weave pattern is it typically sufficient?', '["A shedding system using shaped rotating cams to directly move a small number of heald frames (typically up to 6-8), sufficient for simple weaves like plain or basic twill","A mechanism that controls thousands of individual warp threads for complex jacquard-style patterns","A device used only for inserting weft yarn, unrelated to shedding","A mechanism that can only produce satin weave, never plain or twill"]'::jsonb, 'A shedding system using shaped rotating cams to directly move a small number of heald frames (typically up to 6-8), sufficient for simple weaves like plain or basic twill', 'Tappet (cam) shedding uses precisely shaped rotating cams to directly drive a limited number of heald frames (commonly up to 6-8), making it a simple, robust, and cost-effective choice for simple weave structures like plain weave or basic twills that don''t need more frames.', 1, '{"tappet-shedding"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'What is ''positive let-off'' as opposed to ''negative (friction-brake) let-off'' on a loom?', '["Positive let-off actively drives the warp beam''s release via a controlled gear/motor mechanism synchronized to fabric take-up, rather than relying on a friction brake that simply resists beam rotation","Positive let-off means the warp beam never releases any yarn at all during weaving","Negative let-off actively drives the beam with a motor, while positive let-off uses only a passive friction brake","There is no meaningful difference between positive and negative let-off systems"]'::jsonb, 'Positive let-off actively drives the warp beam''s release via a controlled gear/motor mechanism synchronized to fabric take-up, rather than relying on a friction brake that simply resists beam rotation', 'Positive let-off actively and precisely controls/drives warp release (often electronically synchronized with take-up) for very consistent tension regardless of beam diameter change, whereas negative (friction-brake) let-off simply resists beam rotation passively, requiring periodic adjustment as beam diameter (and thus required braking force) changes through the beam''s life.', 2, '{"positive-negative-letoff"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'What is a ''weft feeder'' (used on many shuttleless looms like rapier or air-jet) responsible for?', '["Pre-measuring and storing a controlled length of weft yarn, then releasing it at high, consistent speed for each pick insertion","Cutting the finished fabric off the loom at the end of a production run","Applying dye directly to the weft yarn as it''s inserted","Permanently removing twist from the weft yarn before insertion"]'::jsonb, 'Pre-measuring and storing a controlled length of weft yarn, then releasing it at high, consistent speed for each pick insertion', 'A weft feeder (accumulator) winds and stores a pre-measured length of weft yarn on a small drum, then releases it rapidly and consistently for each pick — providing controlled, tension-consistent weft delivery essential for high-speed, precise weft insertion on modern shuttleless looms.', 2, '{"weft-feeder"}'::text[]);
COMMIT;
